function monthStart(d = new Date()) { return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01` }
function monthEnd(month: string) { const d = new Date(`${month}T00:00:00`); return new Date(d.getFullYear(), d.getMonth()+1, 0).toISOString().slice(0,10) }
function money(n: number) { return `৳${Number(n||0).toLocaleString('en-BD',{minimumFractionDigits:2,maximumFractionDigits:2})}` }
function dateLabel(value: string, lang: Language) { return new Date(`${value}T00:00:00`).toLocaleDateString(lang==='bn'?'bn-BD':'en-BD',{day:'numeric',month:'short',year:'numeric'}) }
function monthLabel(value: string, lang: Language) { return new Date(`${value.slice(0,7)}-01T00:00:00`).toLocaleDateString(lang==='bn'?'bn-BD':'en-BD',{month:'long',year:'numeric'}) }
function roleLabel(role: AppRole, t: Record<keyof typeof copy.en, string>) { return t[role] }
function errorText(error: unknown) { return error instanceof Error ? error.message : String(error ?? 'Unknown error') }

function SetupScreen() {
  return <div className="splash"><div className="error-card setup-card"><div className="logo-mark large">৳</div><h1>Center Point</h1><h2>Supabase connection is not configured</h2><p>The app itself loaded correctly, but Vite cannot find your Supabase environment variables.</p><div className="setup-steps"><b>Do this in VS Code:</b><ol><li>Open the project folder that contains <code>package.json</code>.</li><li>Create a file named <code>.env.local</code> beside <code>package.json</code>.</li><li>Copy the two lines below into it and replace the second value with your Supabase publishable/anon key.</li></ol><pre>VITE_SUPABASE_URL=https://YOUR_PROJECT.supabase.co
VITE_SUPABASE_ANON_KEY=YOUR_PUBLIC_OR_PUBLISHABLE_KEY</pre><p>Then stop Vite with <code>Ctrl+C</code> and run <code>npm run dev</code> again.</p></div><p className="muted">Your Supabase secret/service-role key must never be placed in this file.</p></div></div>
}

function App() {
  if(!isSupabaseConfigured) return <SetupScreen/>
  const [session,setSession] = useState<Session|null>(null)
  const [profile,setProfile] = useState<Profile|null>(null)
  const [language,setLanguage] = useState<Language>('bn')
  const [loading,setLoading] = useState(true)
  const [profileError,setProfileError] = useState('')
  useEffect(()=>{
    let alive=true
    const boot=async()=>{ const {data}=await supabase.auth.getSession(); if(!alive)return; setSession(data.session); if(data.session) await fetchProfile(data.session.user.id); setLoading(false) }
    const fetchProfile=async(id:string)=>{ const {data,error}=await supabase.from('profiles').select('id,full_name,role,preferred_language,active').eq('id',id).single(); if(error){console.error(error);setProfileError(error.message);return} const p=data as Profile; setProfile(p); setLanguage(p.preferred_language||'bn') }
    void boot()
    const {data:sub}=supabase.auth.onAuthStateChange((_event,next)=>{setSession(next); if(next) void fetchProfile(next.user.id); else setProfile(null)})
    return ()=>{alive=false;sub.subscription.unsubscribe()}
  },[])
  if(loading) return <div className="splash"><div className="logo-mark">৳</div><strong>Building Finance</strong><span>Loading…</span></div>
  if(!session) return <Login language={language} setLanguage={setLanguage}/>
  if(profileError) return <div className="splash"><div className="error-card"><strong>Profile error</strong><p>{profileError}</p><button className="btn primary" onClick={()=>void supabase.auth.signOut()}>Log out</button></div></div>
  if(!profile) return <div className="splash">প্রোফাইল লোড হচ্ছে…</div>
  if(!profile.active) return <div className="splash"><div className="error-card"><strong>{copy[language].inactiveAccount}</strong><button className="btn primary" onClick={()=>void supabase.auth.signOut()}>{copy[language].logout}</button></div></div>
  return <Shell profile={profile} language={language} setLanguage={setLanguage}/>
}

function Login({language,setLanguage}:{language:Language;setLanguage:(v:Language)=>void}){
  const t=copy[language]; const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [busy,setBusy]=useState(false); const [error,setError]=useState('')
  async function submit(e:FormEvent){e.preventDefault();setError('');setBusy(true);const {error}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(error)setError(t.invalidLogin);setBusy(false)}
  return <main className="auth"><section className="auth-panel"><div className="logo-mark large">৳</div><div className="eyebrow">PROPERTY FINANCE</div><h1>{t.title}</h1><p>{t.subtitle}</p><form onSubmit={submit} className="stack"><label>{t.email}<input type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="email" required/></label><label>{t.password}<input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" required/></label>{error&&<div className="alert error">{error}</div>}<button className="btn primary wide" disabled={busy}>{busy?t.loading:t.signIn}</button></form><button className="language-link" onClick={()=>setLanguage(language==='bn'?'en':'bn')}>{t.language}</button></section></main>
}

function Shell({profile,language,setLanguage}:{profile:Profile;language:Language;setLanguage:(v:Language)=>void}){
  const t=copy[language]; const [page,setPage]=useState<Page>('dashboard'); const [toast,setToast]=useState<Toast>(null)
  const canWrite=profile.role==='admin'||profile.role==='manager'
  useEffect(()=>{if(!toast)return;const id=window.setTimeout(()=>setToast(null),3500);return()=>window.clearTimeout(id)},[toast])
  const go=(p:Page)=>setPage(p)
  return <div className="app-shell"><header className="topbar"><div className="brand"><div className="logo-mark">৳</div><div><strong>{t.title}</strong><small>{profile.full_name}</small></div></div><div className="top-actions"><span className="role-pill">{roleLabel(profile.role,t)}</span><button className="icon-btn" onClick={()=>setLanguage(language==='bn'?'en':'bn')}>{language==='bn'?'EN':'বাং'}</button><button className="icon-btn" onClick={()=>void supabase.auth.signOut()}>{t.logout}</button></div></header><main className="content">{page==='dashboard'&&<DashboardPage profile={profile} language={language} onNavigate={go}/>} {page==='income'&&<IncomePage profile={profile} language={language} onToast={setToast}/>} {page==='expected'&&<ExpectedPage profile={profile} language={language} onToast={setToast}/>} {page==='expenses'&&<ExpensePage profile={profile} language={language} onToast={setToast}/>} {page==='properties'&&profile.role==='admin'&&<PropertiesPage profile={profile} language={language} onToast={setToast}/>} {page==='recurring'&&profile.role==='admin'&&<RecurringIncomePage profile={profile} language={language} onToast={setToast}/>} {page==='reports'&&<ReportsPage language={language}/>} {page==='settings'&&profile.role==='admin'&&<SettingsPage profile={profile} language={language} onToast={setToast}/>}</main><nav className="mobile-nav">{([['dashboard','⌂',t.dashboard],['income','↗',t.income],['expected','◷',t.expected],['expenses','↘',t.expenses],['properties','▦',t.properties],['recurring','↻',t.recurring],['reports','▤',t.reports]] as [Page,string,string][]).filter(([p])=>(p!=='properties'&&p!=='recurring')||profile.role==='admin').map(([p,icon,label])=><button key={p} className={page===p?'active':''} onClick={()=>go(p)}><span>{icon}</span>{label}</button>)}{profile.role==='admin'&&<button className={page==='settings'?'active':''} onClick={()=>go('settings')}><span>⚙</span>{t.settings}</button>}</nav>{toast&&<div className={`toast ${toast.type}`}>{toast.text}</div>}</div>
}

function PageHeader({title,subtitle,action}:{title:string;subtitle?:string;action?:ReactNode}){return <div className="page-header"><div><div className="eyebrow">BUILDING FINANCE</div><h1>{title}</h1>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>}
function MonthPicker({value,onChange,language}:{value:string;onChange:(v:string)=>void;language:Language}){const t=copy[language];return <label className="month-picker"><span>{t.month}</span><input type="month" value={value.slice(0,7)} onChange={e=>onChange(`${e.target.value}-01`)}/></label>}

function DashboardPage({profile,language,onNavigate}:{profile:Profile;language:Language;onNavigate:(p:Page)=>void}){
  const t=copy[language]; const [month,setMonth]=useState(monthStart()); const [data,setData]=useState({income:0,expense:0,expected:0,receivedExpected:0}); const [recentIncome,setRecentIncome]=useState<IncomeTransaction[]>([]); const [recentExpense,setRecentExpense]=useState<ExpenseTransaction[]>([]); const [loading,setLoading]=useState(true); const [categories,setCategories]=useState<Category[]>([]); const [properties,setProperties]=useState<Property[]>([])
  const load=useCallback(async()=>{setLoading(true);if(profile.role==='admin'||profile.role==='manager'){await supabase.rpc('generate_monthly_expected_income',{p_month:month})}const end=monthEnd(month);const [inc,exp,expected,cat,prop]=await Promise.all([supabase.from('income_transactions').select('id,transaction_date,amount,category_id,property_id,source_name,payment_method,expected_income_id,note,created_at').gte('transaction_date',month).lte('transaction_date',end).order('transaction_date',{ascending:false}).order('created_at',{ascending:false}).limit(5),supabase.from('expense_transactions').select('id,transaction_date,amount,category_id,property_id,payee,payment_method,note,status,voided_at,void_reason,created_at').gte('transaction_date',month).lte('transaction_date',end).order('transaction_date',{ascending:false}).order('created_at',{ascending:false}).limit(5),supabase.from('expected_income').select('id,property_id,category_id,source_name,expected_amount,period_month,due_date,status,notes,created_by,recurring_income_source_id,created_at,updated_at').eq('period_month',month).neq('status','cancelled'),supabase.from('categories').select('id,name_bn,name_en,category_type,active,sort_order'),supabase.from('properties').select('id,building_id,name,property_type,active,monthly_rent,monthly_service_charge,occupied,occupant_name,notes').eq('active',true)]);const incomeRows=(inc.data??[]) as IncomeTransaction[];const expenseRows=(exp.data??[]) as ExpenseTransaction[];const expectedRows=(expected.data??[]) as ExpectedIncome[];const ids=expectedRows.map(x=>x.id);let received=0;if(ids.length){const {data:p}=await supabase.from('income_transactions').select('expected_income_id,amount').in('expected_income_id',ids);received=(p??[]).reduce((s,r)=>s+Number(r.amount),0)}setRecentIncome(incomeRows);setRecentExpense(expenseRows);setCategories((cat.data??[]) as Category[]);setProperties((prop.data??[]) as Property[]);setData({income:incomeRows.reduce((s,r)=>s+Number(r.amount),0),expense:expenseRows.filter(r=>r.status==='active').reduce((s,r)=>s+Number(r.amount),0),expected:expectedRows.reduce((s,r)=>s+Number(r.expected_amount),0),receivedExpected:received});setLoading(false)},[month]);useEffect(()=>{void load()},[load]);const outstanding=Math.max(data.expected-data.receivedExpected,0);const net=data.income-data.expense;const categoryName=(id:string)=>{const c=categories.find(x=>x.id===id);return c? (language==='bn'?c.name_bn:c.name_en):'—'};const propertyName=(id:string|null)=>properties.find(x=>x.id===id)?.name||'—'
  return <><PageHeader title={t.dashboard} subtitle={`${monthLabel(month,language)} · ${t.dashboardHint}`} action={<MonthPicker value={month} onChange={setMonth} language={language}/>}/><div className="stats-grid"><StatCard label={t.actualIncome} value={money(data.income)} tone="income" loading={loading}/><StatCard label={t.actualExpense} value={money(data.expense)} tone="expense" loading={loading}/><StatCard label={t.netCash} value={money(net)} tone={net>=0?'positive':'negative'} loading={loading}/><StatCard label={t.expectedTotal} value={money(data.expected)} sub={`${t.outstanding}: ${money(outstanding)}`} loading={loading}/></div><section className="quick"><div className="section-title"><h2>{t.quickActions}</h2></div><div className="quick-grid">{canWrite(profile)&&<><button onClick={()=>onNavigate('income')}><span>↗</span><b>{t.addIncome}</b><small>{t.actualIncome}</small></button><button onClick={()=>onNavigate('expected')}><span>◷</span><b>{t.addExpected}</b><small>{t.expectedIncome}</small></button><button onClick={()=>onNavigate('expenses')}><span>↘</span><b>{t.addExpense}</b><small>{t.actualExpense}</small></button></>}<button onClick={()=>onNavigate('reports')}><span>▤</span><b>{t.reports}</b><small>{t.monthlySummary}</small></button>{profile.role==='admin'&&<><button onClick={()=>onNavigate('properties')}><span>▦</span><b>{t.manageProperties}</b><small>{properties.length} {t.units}</small></button><button onClick={()=>onNavigate('settings')}><span>⚙</span><b>{t.manageCategories}</b><small>{categories.length} {t.categories}</small></button><button onClick={()=>onNavigate('recurring')}><span>↻</span><b>{t.recurring}</b><small>{language==='bn'?'মাসিক আয়ের নিয়ম':'Monthly income rules'}</small></button></>}</div></section><div className="two-col"><DataPreview title={t.recentIncome} empty={t.noData} onMore={()=>onNavigate('income')}><div className="preview-list">{recentIncome.length?recentIncome.map(x=><div className="preview-row" key={x.id}><div><b>{x.source_name||categoryName(x.category_id)}</b><small>{propertyName(x.property_id)} · {dateLabel(x.transaction_date,language)}</small></div><strong className="income-text">+{money(Number(x.amount))}</strong></div>):<p className="empty">{t.noData}</p>}</div></DataPreview><DataPreview title={t.recentExpenses} empty={t.noData} onMore={()=>onNavigate('expenses')}><div className="preview-list">{recentExpense.length?recentExpense.map(x=><div className="preview-row" key={x.id}><div><b>{x.payee||categoryName(x.category_id)}</b><small>{propertyName(x.property_id)} · {dateLabel(x.transaction_date,language)}</small></div><strong className="expense-text">−{money(Number(x.amount))}</strong></div>):<p className="empty">{t.noData}</p>}</div></DataPreview></div></>
}
function canWrite(profile:Profile){return profile.role==='admin'||profile.role==='manager'}
function StatCard({label,value,sub,tone='neutral',loading}:{label:string;value:string;sub?:string;tone?:string;loading?:boolean}){return <article className={`stat-card ${tone}`}><span>{label}</span><strong>{loading?'…':value}</strong>{sub&&<small>{sub}</small>}</article>}
function DataPreview({title,onMore,children}:{title:string;empty:string;onMore:()=>void;children:ReactNode}){return <section className="card"><div className="section-title"><h2>{title}</h2><button className="text-btn" onClick={onMore}>View all →</button></div>{children}</section>}

function IncomePage({profile,language,onToast}:{profile:Profile;language:Language;onToast:(v:Toast)=>void}){
 const t=copy[language];const [categories,setCategories]=useState<Category[]>([]);const [properties,setProperties]=useState<Property[]>([]);const [rows,setRows]=useState<IncomeTransaction[]>([]);const [show,setShow]=useState(false);const [busy,setBusy]=useState(false);const [month,setMonth]=useState(monthStart());const [form,setForm]=useState({transaction_date:new Date().toISOString().slice(0,10),amount:'',category_id:'',property_id:'',source_name:'',payment_method:'cash',note:'',expected_income_id:''});const load=useCallback(async()=>{const end=monthEnd(month);const [c,p,i]=await Promise.all([supabase.from('categories').select('id,name_bn,name_en,category_type,active,sort_order').eq('category_type','income').eq('active',true).order('sort_order').order('name_en'),supabase.from('properties').select('id,building_id,name,property_type,active,monthly_rent,monthly_service_charge,occupied,occupant_name,notes').eq('active',true).order('name'),supabase.from('income_transactions').select('id,transaction_date,amount,category_id,property_id,source_name,payment_method,expected_income_id,note,created_at').gte('transaction_date',month).lte('transaction_date',end).order('transaction_date',{ascending:false}).order('created_at',{ascending:false})]);setCategories((c.data??[]) as Category[]);setProperties((p.data??[]) as Property[]);setRows((i.data??[]) as IncomeTransaction[])},[month]);useEffect(()=>{void load()},[load]);const reset=()=>setForm({transaction_date:new Date().toISOString().slice(0,10),amount:'',category_id:'',property_id:'',source_name:'',payment_method:'cash',note:'',expected_income_id:''});async function save(e:FormEvent){e.preventDefault();if(!canWrite(profile)){onToast({type:'error',text:t.noPermission});return}if(!form.category_id||!form.source_name.trim()){onToast({type:'error',text:t.required});return}const amount=Number(form.amount);if(!(amount>0)){onToast({type:'error',text:t.invalidAmount});return}setBusy(true);const {error}=await supabase.from('income_transactions').insert({transaction_date:form.transaction_date,amount,category_id:form.category_id,property_id:form.property_id||null,source_name:form.source_name.trim(),payment_method:form.payment_method,note:form.note.trim()||null,expected_income_id:form.expected_income_id||null,created_by:profile.id});if(error){console.error(error);onToast({type:'error',text:`${t.failed} ${errorText(error)}`});setBusy(false);return}setBusy(false);setShow(false);reset();onToast({type:'success',text:t.incomeAdded});await load()}async function deleteIncome(row:IncomeTransaction){if(profile.role!=='admin')return;if(!window.confirm(t.deleteIncomeConfirm))return;const {error}=await supabase.from('income_transactions').delete().eq('id',row.id);if(error)onToast({type:'error',text:`${t.failed} ${errorText(error)}`});else{onToast({type:'success',text:t.updated});await load()}}const categoryName=(id:string)=>{const c=categories.find(x=>x.id===id);return c?(language==='bn'?c.name_bn:c.name_en):'—'};const propertyName=(id:string|null)=>properties.find(x=>x.id===id)?.name||'—';return <><PageHeader title={t.income} subtitle={`${monthLabel(month,language)} · ${money(rows.reduce((s,r)=>s+Number(r.amount),0))}`} action={<div className="header-actions"><MonthPicker value={month} onChange={setMonth} language={language}/>{canWrite(profile)&&<button className="btn primary" onClick={()=>setShow(v=>!v)}>＋ {t.addIncome}</button>}</div>}/>{show&&<IncomeForm t={t} form={form} setForm={setForm} categories={categories} properties={properties} onCancel={()=>setShow(false)} onSubmit={save} busy={busy}/>}<section className="card"><div className="section-title"><h2>{t.recentIncome}</h2><span className="count">{rows.length}</span></div><div className="table-list">{rows.length?rows.map(x=><div className="ledger-row" key={x.id}><div className="ledger-main"><span className="dot income-dot"/><div><b>{x.source_name||categoryName(x.category_id)}</b><small>{categoryName(x.category_id)} · {propertyName(x.property_id)} · {dateLabel(x.transaction_date,language)}</small>{x.note&&<small>{x.note}</small>}</div></div><div className="ledger-side"><strong className="income-text">+{money(Number(x.amount))}</strong><small>{x.payment_method}</small><ReceiptTools language={language} role={profile.role} transactionType="income" transactionId={x.id} onToast={onToast}/>{profile.role==='admin'&&<button className="text-btn danger" onClick={()=>void deleteIncome(x)}>Delete</button>}</div></div>):<p className="empty">{t.noData}</p>}</div></section></>
}
function IncomeForm({t,form,setForm,categories,properties,onCancel,onSubmit,busy}:{t:Record<keyof typeof copy.en, string>;form:any;setForm:(v:any)=>void;categories:Category[];properties:Property[];onCancel:()=>void;onSubmit:(e:FormEvent)=>void;busy:boolean}){return <form className="card form-card" onSubmit={onSubmit}><div className="section-title"><h2>{t.addIncome}</h2><button type="button" className="icon-btn" onClick={onCancel}>×</button></div><div className="form-grid"><Field label={t.date}><input type="date" value={form.transaction_date} onChange={e=>setForm({...form,transaction_date:e.target.value})} required/></Field><Field label={t.amount}><input type="number" min="0.01" step="0.01" inputMode="decimal" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})} placeholder="0.00" required/></Field><Field label={t.category}><select value={form.category_id} onChange={e=>setForm({...form,category_id:e.target.value})} required><option value="">{t.selectCategory}</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name_en}</option>)}</select></Field><Field label={t.property}><select value={form.property_id} onChange={e=>setForm({...form,property_id:e.target.value})}><option value="">{t.selectProperty}</option>{properties.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label={t.source} wide><input value={form.source_name} onChange={e=>setForm({...form,source_name:e.target.value})} placeholder={t.sourcePlaceholder} required/></Field><Field label={t.payment}><select value={form.payment_method} onChange={e=>setForm({...form,payment_method:e.target.value})}>{(['cash','bank','bkash','nagad','other'] as const).map(v=><option key={v} value={v}>{v==='cash'?t.cash:v==='bank'?t.bank:v==='bkash'?t.bkash:v==='nagad'?t.nagad:t.other}</option>)}</select></Field><Field label={t.note} wide><textarea value={form.note} onChange={e=>setForm({...form,note:e.target.value})} placeholder={t.notePlaceholder} rows={3}/></Field></div><div className="form-actions"><button type="button" className="btn ghost" onClick={onCancel}>{t.cancel}</button><button className="btn primary" disabled={busy}>{busy?t.loading:t.save}</button></div></form>}

function ExpectedPage({profile,language,onToast}:{profile:Profile;language:Language;onToast:(v:Toast)=>void}){
  const t=copy[language]
  const [month,setMonth]=useState(monthStart())
  const [items,setItems]=useState<ExpectedIncome[]>([])
  const [payments,setPayments]=useState<Record<string,number>>({})
  const [cats,setCats]=useState<Category[]>([])
  const [props,setProps]=useState<Property[]>([])
  const [show,setShow]=useState(false)
  const [paymentTarget,setPaymentTarget]=useState<ExpectedIncome|null>(null)
  const [busy,setBusy]=useState(false)
  const [form,setForm]=useState({period_month:monthStart(),due_date:'',expected_amount:'',category_id:'',property_id:'',source_name:'',notes:''})
  const load=useCallback(async()=>{
    if(profile.role==='admin'||profile.role==='manager') await supabase.rpc('generate_monthly_expected_income',{p_month:month})
    const [e,c,p]=await Promise.all([
      supabase.from('expected_income').select('id,property_id,category_id,source_name,expected_amount,period_month,due_date,status,notes,created_by,recurring_income_source_id,created_at,updated_at').eq('period_month',month).order('due_date',{ascending:true,nullsFirst:false}).order('source_name'),
      supabase.from('categories').select('id,name_bn,name_en,category_type,active,sort_order').eq('category_type','income').eq('active',true).order('sort_order'),
      supabase.from('properties').select('id,building_id,name,property_type,active,monthly_rent,monthly_service_charge,occupied,occupant_name,notes').eq('active',true).order('name')
    ])
    const rows=(e.data??[]) as ExpectedIncome[]
    setItems(rows);setCats((c.data??[]) as Category[]);setProps((p.data??[]) as Property[])
    const map:Record<string,number>={}
    if(rows.length){const {data:pay}=await supabase.from('income_transactions').select('expected_income_id,amount').in('expected_income_id',rows.map(x=>x.id));(pay??[]).forEach(r=>{if(r.expected_income_id)map[r.expected_income_id]=(map[r.expected_income_id]||0)+Number(r.amount)})}
    setPayments(map)
  },[month,profile.role])
  useEffect(()=>{void load()},[load])
  useEffect(()=>setForm(f=>({...f,period_month:month})),[month])
  async function deleteExpected(item:ExpectedIncome){
    if(profile.role!=='admin')return
    const hasPayments=(payments[item.id]||0)>0
    if(!window.confirm(hasPayments?t.deleteExpectedWithPaymentsConfirm:t.deleteExpectedConfirm))return
    const {error}=await supabase.from('expected_income').delete().eq('id',item.id)
    if(error)onToast({type:'error',text:`${t.failed} ${errorText(error)}`});else{onToast({type:'success',text:t.updated});await load()}
  }
  async function save(e:FormEvent){
    e.preventDefault();if(!canWrite(profile)){onToast({type:'error',text:t.noPermission});return}
    const amount=Number(form.expected_amount);if(!(amount>0)||!form.category_id||!form.source_name.trim()){onToast({type:'error',text:t.required});return}
    setBusy(true)
    const {error}=await supabase.from('expected_income').insert({period_month:form.period_month,due_date:form.due_date||null,expected_amount:amount,category_id:form.category_id,property_id:form.property_id||null,source_name:form.source_name.trim(),notes:form.notes.trim()||null,created_by:profile.id,status:'pending'})
    setBusy(false)
    if(error){onToast({type:'error',text:`${t.failed} ${errorText(error)}`});return}
    setShow(false);setForm({period_month:month,due_date:'',expected_amount:'',category_id:'',property_id:'',source_name:'',notes:''});onToast({type:'success',text:t.expectedAdded});await load()
  }
  async function cancel(id:string){
    if(!canWrite(profile)||!window.confirm(t.confirmCancel))return
    const {error}=await supabase.from('expected_income').update({status:'cancelled'}).eq('id',id)
    if(error)onToast({type:'error',text:`${t.failed} ${errorText(error)}`});else{onToast({type:'success',text:t.updated});await load()}
  }
  async function generate(){
    if(!canWrite(profile))return;setBusy(true)
    const {error}=await supabase.rpc('generate_monthly_expected_income',{p_month:month});setBusy(false)
    if(error)onToast({type:'error',text:`${t.failed} ${errorText(error)}`});else{onToast({type:'success',text:t.generated});await load()}
  }
  const catName=(id:string)=>{const c=cats.find(x=>x.id===id);return c?(language==='bn'?c.name_bn:c.name_en):'—'}
  const propName=(id:string|null)=>props.find(x=>x.id===id)?.name||'—'
  const expectedTotal=items.filter(x=>x.status!=='cancelled').reduce((s,x)=>s+Number(x.expected_amount),0)
  const receivedTotal=items.reduce((s,x)=>s+(payments[x.id]||0),0)
  const outstanding=Math.max(expectedTotal-receivedTotal,0)
  return <>
    <PageHeader title={t.expectedIncome} subtitle={`${monthLabel(month,language)} · ${t.outstanding}: ${money(outstanding)}`} action={<div className="header-actions"><MonthPicker value={month} onChange={setMonth} language={language}/>{canWrite(profile)&&<><button className="btn secondary" onClick={()=>void generate()} disabled={busy}>↻ {language==='bn'?'আপডেট':'Refresh'}</button><button className="btn primary" onClick={()=>setShow(v=>!v)}>＋ {t.addExpected}</button></>}</div>}/>
    <div className="info-banner">{language==='bn'?'নিয়মিত আয়ের source একবার যোগ করলে প্রতি মাসের expectation নিজে থেকেই তৈরি হবে। এখানে শুধু টাকা পাওয়ার সময় Record payment চাপুন।':'Recurring income sources generate monthly expectations automatically. Here you only need to record the payment when money arrives.'}</div>
    {show&&<ExpectedForm t={t} form={form} setForm={setForm} cats={cats} props={props} onCancel={()=>setShow(false)} onSubmit={save} busy={busy}/>} 
    <section className="card"><div className="summary-inline"><div><span>{t.expectedTotal}</span><strong>{money(expectedTotal)}</strong></div><div><span>{t.received}</span><strong>{money(receivedTotal)}</strong></div><div><span>{t.outstanding}</span><strong>{money(outstanding)}</strong></div></div></section>
    <section className="expected-list">{items.length?items.map(item=>{const received=payments[item.id]||0;const due=Math.max(Number(item.expected_amount)-received,0);const status=item.status==='cancelled'?'cancelled':due<=0?'received':received>0?'partially_received':'pending';return <article className="expected-card" key={item.id}><div className="expected-top"><div><b>{item.source_name}</b><small>{catName(item.category_id)} · {propName(item.property_id)}{item.due_date?` · ${t.dueDate}: ${dateLabel(item.due_date,language)}`:''}</small></div><Status status={status} t={t}/></div><div className="expected-values"><div><span>{t.expected}</span><b>{money(Number(item.expected_amount))}</b></div><div><span>{t.received}</span><b>{money(received)}</b></div><div><span>{t.outstanding}</span><b className={due?'warning-text':''}>{money(due)}</b></div></div>{canWrite(profile)&&status!=='cancelled'&&due>0&&<div className="expected-actions"><button className="btn primary small" onClick={()=>setPaymentTarget(item)}>{t.recordPayment}</button><button className="text-btn danger" onClick={()=>void cancel(item.id)}>{t.cancelExpected}</button></div>}{profile.role==='admin'&&<div className="expected-actions admin-actions"><button className="text-btn danger" onClick={()=>void deleteExpected(item)}>{t.delete}</button></div>}{status==='received'&&<div className="success-line">✓ {t.fullyReceived}</div>}</article>}) : <section className="card empty-state"><span>◷</span><b>{t.noData}</b><small>{language==='bn'?'এই মাসের জন্য কোনো expectation নেই।':'No expectations for this month yet.'}</small></section>}</section>
    {paymentTarget&&<PaymentModal target={paymentTarget} received={payments[paymentTarget.id]||0} profile={profile} language={language} onClose={()=>setPaymentTarget(null)} onDone={async()=>{setPaymentTarget(null);onToast({type:'success',text:t.paymentRecorded});await load()}} onToast={onToast}/>} 
  </>
}
function ExpectedForm({t,form,setForm,cats,props,onCancel,onSubmit,busy}:{t:Record<keyof typeof copy.en, string>;form:any;setForm:(v:any)=>void;cats:Category[];props:Property[];onCancel:()=>void;onSubmit:(e:FormEvent)=>void;busy:boolean}){return <form className="card form-card" onSubmit={onSubmit}><div className="section-title"><h2>{t.addExpected}</h2><button type="button" className="icon-btn" onClick={onCancel}>×</button></div><div className="form-grid"><Field label={t.month}><input type="month" value={form.period_month.slice(0,7)} onChange={e=>setForm({...form,period_month:`${e.target.value}-01`})} required/></Field><Field label={t.expectedAmount}><input type="number" min="0.01" step="0.01" value={form.expected_amount} onChange={e=>setForm({...form,expected_amount:e.target.value})} required/></Field><Field label={t.category}><select value={form.category_id} onChange={e=>setForm({...form,category_id:e.target.value})} required><option value="">{t.selectCategory}</option>{cats.map(c=><option key={c.id} value={c.id}>{c.name_en}</option>)}</select></Field><Field label={t.property}><select value={form.property_id} onChange={e=>setForm({...form,property_id:e.target.value})}><option value="">{t.selectProperty}</option>{props.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label={t.source} wide><input value={form.source_name} onChange={e=>setForm({...form,source_name:e.target.value})} placeholder={t.sourcePlaceholder} required/></Field><Field label={t.dueDate}><input type="date" value={form.due_date} onChange={e=>setForm({...form,due_date:e.target.value})}/></Field><Field label={t.note} wide><textarea rows={3} value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></Field></div><div className="form-actions"><button type="button" className="btn ghost" onClick={onCancel}>{t.cancel}</button><button className="btn primary" disabled={busy}>{busy?t.loading:t.save}</button></div></form>}
function PaymentModal({target,received,profile,language,onClose,onDone,onToast}:{target:ExpectedIncome;received:number;profile:Profile;language:Language;onClose:()=>void;onDone:()=>Promise<void>;onToast:(v:Toast)=>void}){const t=copy[language];const outstanding=Math.max(Number(target.expected_amount)-received,0);const [amount,setAmount]=useState(String(outstanding));const [date,setDate]=useState(new Date().toISOString().slice(0,10));const [method,setMethod]=useState('cash');const [note,setNote]=useState('');const [busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();const n=Number(amount);if(!(n>0)||n>outstanding){onToast({type:'error',text:n>outstanding?t.amountTooHigh:t.invalidAmount});return}setBusy(true);const {error}=await supabase.from('income_transactions').insert({transaction_date:date,amount:n,category_id:target.category_id,property_id:target.property_id,source_name:target.source_name,payment_method:method,note:note.trim()||null,expected_income_id:target.id,created_by:profile.id});if(error){setBusy(false);onToast({type:'error',text:`${t.failed} ${errorText(error)}`});return}const newReceived=received+n;const status=newReceived>=Number(target.expected_amount)?'received':'partially_received';const {error:statusError}=await supabase.from('expected_income').update({status}).eq('id',target.id);if(statusError){setBusy(false);onToast({type:'error',text:`${t.failed} ${errorText(statusError)}`});return}setBusy(false);await onDone()}return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><div className="section-title"><div><h2>{t.recordPayment}</h2><p>{target.source_name} · {t.outstanding}: {money(outstanding)}</p></div><button type="button" className="icon-btn" onClick={onClose}>×</button></div><div className="form-grid"><Field label={t.amount}><input autoFocus type="number" min="0.01" max={outstanding} step="0.01" value={amount} onChange={e=>setAmount(e.target.value)} required/></Field><Field label={t.date}><input type="date" value={date} onChange={e=>setDate(e.target.value)} required/></Field><Field label={t.payment}><select value={method} onChange={e=>setMethod(e.target.value)}>{(['cash','bank','bkash','nagad','other'] as const).map(v=><option key={v} value={v}>{v}</option>)}</select></Field><Field label={t.note} wide><textarea rows={3} value={note} onChange={e=>setNote(e.target.value)}/></Field></div><div className="form-actions"><button type="button" className="btn ghost" onClick={onClose}>{t.cancel}</button><button className="btn primary" disabled={busy}>{busy?t.loading:t.recordPayment}</button></div></form></div>}
function Status({status,t}:{status:string;t:Record<keyof typeof copy.en, string>}){const label=status==='pending'?t.pending:status==='partially_received'?t.partial:status==='received'?t.fullyReceived:t.cancelled;return <span className={`status-badge ${status}`}>{label}</span>}
function ActivityBadge({active,t}:{active:boolean;t:Record<keyof typeof copy.en, string>}){return <span className={`status-badge ${active?'active':'cancelled'}`}>{active?t.active:t.inactive}</span>}

function ExpensePage({profile,language,onToast}:{profile:Profile;language:Language;onToast:(v:Toast)=>void}){
 const t=copy[language];const [month,setMonth]=useState(monthStart());const [cats,setCats]=useState<Category[]>([]);const [props,setProps]=useState<Property[]>([]);const [rows,setRows]=useState<ExpenseTransaction[]>([]);const [show,setShow]=useState(false);const [busy,setBusy]=useState(false);const [form,setForm]=useState({transaction_date:new Date().toISOString().slice(0,10),amount:'',category_id:'',property_id:'',payee:'',payment_method:'cash',note:''})
 const load=useCallback(async()=>{const end=monthEnd(month);const [c,p,e]=await Promise.all([supabase.from('categories').select('id,name_bn,name_en,category_type,active,sort_order').eq('category_type','expense').eq('active',true).order('sort_order').order('name_en'),supabase.from('properties').select('id,building_id,name,property_type,active,monthly_rent,monthly_service_charge,occupied,occupant_name,notes').eq('active',true).order('name'),supabase.from('expense_transactions').select('id,transaction_date,amount,category_id,property_id,payee,payment_method,note,status,voided_at,void_reason,created_at').gte('transaction_date',month).lte('transaction_date',end).order('transaction_date',{ascending:false}).order('created_at',{ascending:false})]);setCats((c.data??[]) as Category[]);setProps((p.data??[]) as Property[]);setRows((e.data??[]) as ExpenseTransaction[])},[month])
 useEffect(()=>{void load()},[load])
 async function save(e:FormEvent){e.preventDefault();if(!canWrite(profile)){onToast({type:'error',text:t.noPermission});return}const n=Number(form.amount);if(!(n>0)||!form.category_id){onToast({type:'error',text:t.required});return}setBusy(true);const {error}=await supabase.from('expense_transactions').insert({transaction_date:form.transaction_date,amount:n,category_id:form.category_id,property_id:form.property_id||null,payee:form.payee.trim()||null,payment_method:form.payment_method,note:form.note.trim()||null,created_by:profile.id,status:'active'});setBusy(false);if(error){onToast({type:'error',text:`${t.failed} ${errorText(error)}`});return}setShow(false);setForm({transaction_date:new Date().toISOString().slice(0,10),amount:'',category_id:'',property_id:'',payee:'',payment_method:'cash',note:''});onToast({type:'success',text:t.expenseAdded});await load()}
 async function voidExpense(row:ExpenseTransaction){if(!canWrite(profile)||row.status==='voided')return;const reason=window.prompt(t.voidReason);if(!reason?.trim())return;const {error}=await supabase.from('expense_transactions').update({status:'voided',voided_at:new Date().toISOString(),void_reason:reason.trim()}).eq('id',row.id);if(error)onToast({type:'error',text:`${t.failed} ${errorText(error)}`});else{onToast({type:'success',text:t.updated});await load()}}
 async function deleteExpense(row:ExpenseTransaction){if(profile.role!=='admin'||!window.confirm('Permanently delete this expense? This cannot be undone.'))return;const {error}=await supabase.from('expense_transactions').delete().eq('id',row.id);if(error)onToast({type:'error',text:`${t.failed} ${errorText(error)}`});else{onToast({type:'success',text:t.updated});await load()}}
 const catName=(id:string)=>{const c=cats.find(x=>x.id===id);return c?(language==='bn'?c.name_bn:c.name_en):'—'};const propName=(id:string|null)=>props.find(x=>x.id===id)?.name||'—'
 return <><PageHeader title={t.expenses} subtitle={`${monthLabel(month,language)} · ${money(rows.filter(x=>x.status==='active').reduce((s,x)=>s+Number(x.amount),0))}`} action={<div className="header-actions"><MonthPicker value={month} onChange={setMonth} language={language}/>{canWrite(profile)&&<button className="btn primary" onClick={()=>setShow(v=>!v)}>＋ {t.addExpense}</button>}</div>}/>{show&&<ExpenseForm t={t} form={form} setForm={setForm} cats={cats} props={props} onCancel={()=>setShow(false)} onSubmit={save} busy={busy}/>}<section className="card"><div className="table-list">{rows.length?rows.map(x=><div className={`ledger-row ${x.status==='voided'?'voided':''}`} key={x.id}><div className="ledger-main"><span className="dot expense-dot"/><div><b>{x.payee||catName(x.category_id)}</b><small>{catName(x.category_id)} · {propName(x.property_id)} · {dateLabel(x.transaction_date,language)}</small>{x.note&&<small>{x.note}</small>}{x.status==='voided'&&<small className="danger">{t.voided}: {x.void_reason||'—'}</small>}</div></div><div className="ledger-side"><strong className="expense-text">−{money(Number(x.amount))}</strong>{x.status==='active'&&canWrite(profile)&&<button className="text-btn danger" onClick={()=>void voidExpense(x)}>{t.void}</button>}<ReceiptTools language={language} role={profile.role} transactionType="expense" transactionId={x.id} onToast={onToast}/>{profile.role==='admin'&&<button className="text-btn danger" onClick={()=>void deleteExpense(x)}>Delete</button>}</div></div>):<p className="empty">{t.noData}</p>}</div></section></>
}
function ExpenseForm({t,form,setForm,cats,props,onCancel,onSubmit,busy}:{t:Record<keyof typeof copy.en, string>;form:any;setForm:(v:any)=>void;cats:Category[];props:Property[];onCancel:()=>void;onSubmit:(e:FormEvent)=>void;busy:boolean}){return <form className="card form-card" onSubmit={onSubmit}><div className="section-title"><h2>{t.addExpense}</h2><button type="button" className="icon-btn" onClick={onCancel}>×</button></div><div className="form-grid"><Field label={t.date}><input type="date" value={form.transaction_date} onChange={e=>setForm({...form,transaction_date:e.target.value})} required/></Field><Field label={t.amount}><input type="number" min="0.01" step="0.01" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})} required/></Field><Field label={t.category}><select value={form.category_id} onChange={e=>setForm({...form,category_id:e.target.value})} required><option value="">{t.selectCategory}</option>{cats.map(c=><option key={c.id} value={c.id}>{c.name_en}</option>)}</select></Field><Field label={t.property}><select value={form.property_id} onChange={e=>setForm({...form,property_id:e.target.value})}><option value="">{t.selectProperty}</option>{props.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label={t.paidTo} wide><input value={form.payee} onChange={e=>setForm({...form,payee:e.target.value})} placeholder={t.payeePlaceholder}/></Field><Field label={t.payment}><select value={form.payment_method} onChange={e=>setForm({...form,payment_method:e.target.value})}>{(['cash','bank','bkash','nagad','other'] as const).map(v=><option key={v} value={v}>{v}</option>)}</select></Field><Field label={t.note} wide><textarea rows={3} value={form.note} onChange={e=>setForm({...form,note:e.target.value})}/></Field></div><div className="form-actions"><button type="button" className="btn ghost" onClick={onCancel}>{t.cancel}</button><button className="btn primary" disabled={busy}>{busy?t.loading:t.save}</button></div></form>}

function ReportsPage({language}:{language:Language}){const t=copy[language];const [rows,setRows]=useState<any[]>([]);const [loading,setLoading]=useState(true);const load=useCallback(async()=>{setLoading(true);const {data,error}=await supabase.from('monthly_financial_summary').select('month_start,total_income,total_expense,net_cash_flow').order('month_start',{ascending:false}).limit(24);if(error)console.error(error);setRows(data??[]);setLoading(false)},[]);useEffect(()=>{void load()},[load]);return <><PageHeader title={t.reports} subtitle={t.monthlySummary} action={<button className="btn secondary" onClick={()=>void load()}>{t.refresh}</button>}/><section className="card"><div className="table-list">{loading?<p className="empty">{t.loading}</p>:rows.length?rows.map(r=><div className="ledger-row" key={r.month_start}><div><b>{monthLabel(String(r.month_start),language)}</b><small>{t.actualIncome}: {money(Number(r.total_income))} · {t.actualExpense}: {money(Number(r.total_expense))}</small></div><div className="ledger-side"><strong className={Number(r.net_cash_flow)>=0?'income-text':'expense-text'}>{money(Number(r.net_cash_flow))}</strong><small>{t.netCash}</small></div></div>):<p className="empty">{t.noData}</p>}</div></section></>}

function RecurringIncomePage({profile,language,onToast}:{profile:Profile;language:Language;onToast:(v:Toast)=>void}){
 const t=copy[language];const [rows,setRows]=useState<RecurringIncomeSource[]>([]);const [cats,setCats]=useState<Category[]>([]);const [props,setProps]=useState<Property[]>([]);const [show,setShow]=useState(false);const [editing,setEditing]=useState<RecurringIncomeSource|null>(null);const [busy,setBusy]=useState(false);
 const empty={property_id:'',category_id:'',source_name:'',monthly_amount:'',start_month:monthStart(),end_month:'',notes:''};const [form,setForm]=useState<any>(empty);
 const load=useCallback(async()=>{const [r,c,p]=await Promise.all([supabase.from('recurring_income_sources').select('id,property_id,category_id,source_name,monthly_amount,start_month,end_month,active,notes,created_by,created_at,updated_at').order('active',{ascending:false}).order('source_name'),supabase.from('categories').select('id,name_bn,name_en,category_type,active,sort_order').eq('category_type','income').order('sort_order').order('name_en'),supabase.from('properties').select('id,building_id,name,property_type,active,monthly_rent,monthly_service_charge,occupied,occupant_name,notes').order('name')]);setRows((r.data??[]) as RecurringIncomeSource[]);setCats((c.data??[]) as Category[]);setProps((p.data??[]) as Property[])},[]);
 useEffect(()=>{void load()},[load]);
 function startAdd(){setEditing(null);setForm({...empty});setShow(true)}
 function startEdit(row:RecurringIncomeSource){setEditing(row);setForm({property_id:row.property_id||'',category_id:row.category_id,source_name:row.source_name,monthly_amount:String(row.monthly_amount),start_month:row.start_month,end_month:row.end_month||'',notes:row.notes||''});setShow(true)}
 async function save(e:FormEvent){e.preventDefault();if(profile.role!=='admin')return;const amount=Number(form.monthly_amount);if(!(amount>0)||!form.category_id||!form.source_name.trim()||!form.start_month){onToast({type:'error',text:t.required});return}setBusy(true);const payload={property_id:form.property_id||null,category_id:form.category_id,source_name:form.source_name.trim(),monthly_amount:amount,start_month:`${form.start_month.slice(0,7)}-01`,end_month:form.end_month?`${form.end_month.slice(0,7)}-01`:null,notes:form.notes.trim()||null};const q=editing?supabase.from('recurring_income_sources').update(payload).eq('id',editing.id):supabase.from('recurring_income_sources').insert({...payload,created_by:profile.id});const {error}=await q;if(error){setBusy(false);onToast({type:'error',text:`${t.failed} ${errorText(error)}`});return}await supabase.rpc('generate_monthly_expected_income',{p_month:monthStart()});setBusy(false);setShow(false);onToast({type:'success',text:editing?t.recurringUpdated:t.recurringAdded});await load()}
 async function toggle(row:RecurringIncomeSource){const {error}=await supabase.from('recurring_income_sources').update({active:!row.active,end_month:row.active?monthStart():null}).eq('id',row.id);if(error)onToast({type:'error',text:`${t.failed} ${errorText(error)}`});else{onToast({type:'success',text:t.updated});await load()}}
 const propName=(id:string|null)=>props.find(p=>p.id===id)?.name||'General income';const catName=(id:string)=>{const c=cats.find(x=>x.id===id);return c?(language==='bn'?c.name_bn:c.name_en):'—'};
 return <><PageHeader title={t.recurring} subtitle={language==='bn'?'একবার যোগ করুন—এরপর প্রতি মাসের প্রত্যাশিত আয় নিজে থেকেই তৈরি হবে।':'Add each regular income once. Every month, the expected amount is created automatically.'} action={<button className="btn primary" onClick={startAdd}>＋ {t.add}</button>}/><section className="card friendly-help"><b>{language==='bn'?'এটি কীভাবে কাজ করে':'How this works'}</b><p>{language==='bn'?'ফ্ল্যাট/দোকান, মাসিক টাকা ও শুরু মাস একবার দিন। ভাড়াটিয়া টাকা দিলে Expected থেকে Received চাপুন। ভাড়াটিয়া চলে গেলে Deactivate করুন—পুরনো হিসাব থাকবে, ভবিষ্যতের expectation বন্ধ হবে।':'Enter the flat/shop, monthly amount and start month once. When money arrives, use Record payment in Expected. When a tenant leaves, deactivate the source; history stays and future expectations stop.'}</p></section>{show&&<form className="card form-card" onSubmit={save}><div className="section-title"><div><h2>{editing?t.edit:t.add} {t.recurring}</h2><small>{language==='bn'?'ভবিষ্যতের মাসগুলোতে এই নিয়ম ব্যবহার হবে।':'This rule controls future monthly expectations.'}</small></div><button type="button" className="icon-btn" onClick={()=>setShow(false)}>×</button></div><div className="form-grid"><Field label={t.property}><select value={form.property_id} onChange={e=>{const id=e.target.value;const p=props.find(x=>x.id===id);setForm({...form,property_id:id,source_name:form.source_name||(p?.name||'')})}}><option value="">{language==='bn'?'সাধারণ আয়':'General income'}</option>{props.map(p=><option key={p.id} value={p.id}>{p.name} {p.occupied?'':'(vacant)'}</option>)}</select></Field><Field label={t.category}><select value={form.category_id} onChange={e=>setForm({...form,category_id:e.target.value})} required><option value="">{t.selectCategory}</option>{cats.map(c=><option key={c.id} value={c.id}>{language==='bn'?c.name_bn:c.name_en}</option>)}</select></Field><Field label={t.source}><input value={form.source_name} onChange={e=>setForm({...form,source_name:e.target.value})} placeholder={t.sourcePlaceholder} required/></Field><Field label={t.amount}><input type="number" min="0.01" step="0.01" inputMode="decimal" value={form.monthly_amount} onChange={e=>setForm({...form,monthly_amount:e.target.value})} required/></Field><Field label={t.month}><input type="month" value={form.start_month.slice(0,7)} onChange={e=>setForm({...form,start_month:`${e.target.value}-01`})} required/></Field><Field label={language==='bn'?'শেষ মাস (ঐচ্ছিক)':'End month (optional)'}><input type="month" value={form.end_month?form.end_month.slice(0,7):''} onChange={e=>setForm({...form,end_month:e.target.value?`${e.target.value}-01`:''})}/></Field><Field label={t.note} wide><textarea rows={3} value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></Field></div><div className="form-actions"><button type="button" className="btn ghost" onClick={()=>setShow(false)}>{t.cancel}</button><button className="btn primary" disabled={busy}>{busy?t.loading:t.save}</button></div></form>}<section className="card"><div className="section-title"><h2>{t.recurring}</h2><span className="count">{rows.filter(r=>r.active).length} {t.activeCount}</span></div><div className="table-list">{rows.length?rows.map(r=><div className={`ledger-row ${!r.active?'muted-row':''}`} key={r.id}><div className="ledger-main"><span className="dot income-dot"/><div><b>{r.source_name}</b><small>{propName(r.property_id)} · {catName(r.category_id)} · {money(Number(r.monthly_amount))}/month</small><small>{r.start_month.slice(0,7)} → {r.end_month?r.end_month.slice(0,7):t.ongoing}</small></div></div><div className="ledger-side"><ActivityBadge active={r.active} t={t}/><div><button className="text-btn" onClick={()=>startEdit(r)}>{t.edit}</button><button className="text-btn" onClick={()=>void toggle(r)}>{r.active?t.disable:t.enable}</button></div></div></div>):<p className="empty">{t.noData}</p>}</div></section></>}

function PropertiesPage({profile,language,onToast}:{profile:Profile;language:Language;onToast:(v:Toast)=>void}){const t=copy[language];const [buildings,setBuildings]=useState<any[]>([]);const [props,setProps]=useState<Property[]>([]);const [showB,setShowB]=useState(false);const [showP,setShowP]=useState(false);const [edit,setEdit]=useState<Property|null>(null);const [editBuilding,setEditBuilding]=useState<any>(null);const load=useCallback(async()=>{const [b,p]=await Promise.all([supabase.from('buildings').select('id,name,address,active').order('name'),supabase.from('properties').select('id,building_id,name,property_type,active,monthly_rent,monthly_service_charge,occupied,occupant_name,notes').order('name')]);setBuildings(b.data??[]);setProps((p.data??[]) as Property[])},[]);useEffect(()=>{void load()},[load]);async function toggle(table:'buildings'|'properties',row:any){const {error}=await supabase.from(table).update({active:!row.active}).eq('id',row.id);if(error)onToast({type:'error',text:`${t.failed} ${errorText(error)}`});else{onToast({type:'success',text:t.updated});await load()}}const total=props.reduce((s,p)=>s+Number(p.monthly_rent||0)+Number(p.monthly_service_charge||0),0);const occupied=props.filter(p=>p.occupied&&p.active).length;return <><PageHeader title={t.properties} subtitle={`${props.length} ${t.units} · ${t.occupancy}: ${occupied} · ${t.monthlyRecurring}: ${money(total)}`} action={<div className="header-actions"><button className="btn secondary" onClick={()=>setShowB(v=>!v)}>＋ {t.addBuilding}</button><button className="btn primary" onClick={()=>{if(!buildings.length)onToast({type:'error',text:t.noBuildingsError});else setShowP(v=>!v)}}>＋ {t.addProperty}</button></div>}/>{showB&&<BuildingForm t={t} existing={null} onCancel={()=>setShowB(false)} onDone={async()=>{setShowB(false);onToast({type:'success',text:t.buildingAdded});await load()}}/>}{editBuilding&&<BuildingForm t={t} existing={editBuilding} onCancel={()=>setEditBuilding(null)} onDone={async()=>{setEditBuilding(null);onToast({type:'success',text:t.updated});await load()}}/>}{(showP||edit)&&<PropertyForm t={t} buildings={buildings.filter(b=>b.active)} existing={edit} onCancel={()=>{setShowP(false);setEdit(null)}} onDone={async()=>{setShowP(false);setEdit(null);onToast({type:'success',text:edit?t.updated:t.propertyAdded});await load()}}/>}<div className="two-col"><section className="card"><div className="section-title"><h2>{t.building}</h2><span className="count">{buildings.length}</span></div><div className="table-list">{buildings.length?buildings.map(b=><div className="ledger-row" key={b.id}><div className="ledger-main"><span className="dot building-dot"/><div><b>{b.name}</b><small>{b.address||'—'}</small></div></div><div className="ledger-side"><ActivityBadge active={b.active} t={t}/><button className="text-btn" onClick={()=>void toggle('buildings',b)}>{b.active?t.disable:t.enable}</button><button className="text-btn" onClick={()=>setEditBuilding(b)}>{t.edit}</button></div></div>):<p className="empty">{t.noBuildings}</p>}</div></section><section className="card"><div className="section-title"><h2>{t.properties}</h2><span className="count">{props.length}</span></div><div className="table-list">{props.length?props.map(p=>{const b=buildings.find(x=>x.id===p.building_id);return <div className="ledger-row" key={p.id}><div className="ledger-main"><span className="dot property-dot"/><div><b>{p.name}</b><small>{b?.name||'—'} · {p.property_type==='apartment'?t.apartment:p.property_type==='shop'?t.shop:t.otherType} · {p.occupied?t.occupied:t.vacant}</small><small>{p.occupied&&p.occupant_name?p.occupant_name:'—'}</small></div></div><div className="ledger-side"><strong>{money(Number(p.monthly_rent||0)+Number(p.monthly_service_charge||0))}</strong><small>{t.rent}: {money(Number(p.monthly_rent||0))} · {t.service}: {money(Number(p.monthly_service_charge||0))}</small><div><button className="text-btn" onClick={()=>setEdit(p)}>{t.edit}</button><button className="text-btn" onClick={()=>void toggle('properties',p)}>{p.active?t.disable:t.enable}</button></div></div></div>}) : <p className="empty">{t.noProperties}</p>}</div></section></div></>}
function BuildingForm({t,existing,onCancel,onDone}:{t:Record<keyof typeof copy.en,string>;existing:any|null;onCancel:()=>void;onDone:()=>Promise<void>}){const [name,setName]=useState(existing?.name||'');const [address,setAddress]=useState(existing?.address||'');const [busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();if(!name.trim())return;setBusy(true);const q=existing?supabase.from('buildings').update({name:name.trim(),address:address.trim()||null}).eq('id',existing.id):supabase.from('buildings').insert({name:name.trim(),address:address.trim()||null});const {error}=await q;setBusy(false);if(error){alert(error.message);return}await onDone()}return <form className="card form-card" onSubmit={submit}><div className="section-title"><h2>{existing?t.editBuilding:t.addBuilding}</h2><button type="button" className="icon-btn" onClick={onCancel}>×</button></div><div className="form-grid"><Field label={t.buildingName}><input value={name} onChange={e=>setName(e.target.value)} required/></Field><Field label={t.address}><input value={address} onChange={e=>setAddress(e.target.value)}/></Field></div><div className="form-actions"><button type="button" className="btn ghost" onClick={onCancel}>{t.cancel}</button><button className="btn primary" disabled={busy}>{busy?t.loading:t.save}</button></div></form>}
function PropertyForm({t,buildings,existing,onCancel,onDone}:{t:Record<keyof typeof copy.en, string>;buildings:any[];existing:Property|null;onCancel:()=>void;onDone:()=>Promise<void>}){const [buildingId,setBuildingId]=useState(existing?.building_id||buildings[0]?.id||'');const [name,setName]=useState(existing?.name||'');const [type,setType]=useState<any>(existing?.property_type||'apartment');const [rent,setRent]=useState(String(existing?.monthly_rent||''));const [service,setService]=useState(String(existing?.monthly_service_charge||''));const [occupied,setOccupied]=useState(existing?.occupied??true);const [occupant,setOccupant]=useState(existing?.occupant_name||'');const [notes,setNotes]=useState(existing?.notes||'');const [busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();if(!buildingId||!name.trim())return;setBusy(true);const payload={building_id:buildingId,name:name.trim(),property_type:type,monthly_rent:Number(rent)||0,monthly_service_charge:Number(service)||0,occupied,occupant_name:occupied?(occupant.trim()||null):null,notes:notes.trim()||null};const q=existing?supabase.from('properties').update(payload).eq('id',existing.id):supabase.from('properties').insert(payload);const {error}=await q;setBusy(false);if(error){alert(error.message);return}await onDone()}return <form className="card form-card" onSubmit={submit}><div className="section-title"><h2>{existing?t.editProperty:t.addProperty}</h2><button type="button" className="icon-btn" onClick={onCancel}>×</button></div><div className="form-grid"><Field label={t.building}><select value={buildingId} onChange={e=>setBuildingId(e.target.value)} required><option value="">{t.select}</option>{buildings.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></Field><Field label={t.unitName}><input value={name} onChange={e=>setName(e.target.value)} required/></Field><Field label={t.type}><select value={type} onChange={e=>setType(e.target.value)}><option value="apartment">{t.apartment}</option><option value="shop">{t.shop}</option><option value="other">{t.otherType}</option></select></Field><Field label={t.rent}><input type="number" min="0" step="0.01" value={rent} onChange={e=>setRent(e.target.value)}/></Field><Field label={t.service}><input type="number" min="0" step="0.01" value={service} onChange={e=>setService(e.target.value)}/></Field><Field label={t.occupant}><input value={occupant} disabled={!occupied} onChange={e=>setOccupant(e.target.value)}/></Field><label className="check"><input type="checkbox" checked={occupied} onChange={e=>setOccupied(e.target.checked)}/><span>{occupied?t.occupied:t.vacant}</span></label><Field label={t.notes} wide><textarea rows={3} value={notes} onChange={e=>setNotes(e.target.value)}/></Field></div><div className="form-actions"><button type="button" className="btn ghost" onClick={onCancel}>{t.cancel}</button><button className="btn primary" disabled={busy}>{busy?t.loading:t.save}</button></div></form>}

function SettingsPage({profile,language,onToast}:{profile:Profile;language:Language;onToast:(v:Toast)=>void}){const t=copy[language];const [cats,setCats]=useState<Category[]>([]);const [type,setType]=useState<'income'|'expense'>('income');const [form,setForm]=useState({name_bn:'',name_en:''});const load=useCallback(async()=>{const {data,error}=await supabase.from('categories').select('id,name_bn,name_en,category_type,active,sort_order').order('category_type').order('sort_order').order('name_en');if(error)onToast({type:'error',text:errorText(error)});else setCats((data??[]) as Category[])},[onToast]);useEffect(()=>{void load()},[load]);async function add(e:FormEvent){e.preventDefault();if(!form.name_en.trim())return;const max=Math.max(0,...cats.filter(c=>c.category_type===type).map(c=>c.sort_order));const {error}=await supabase.from('categories').insert({name_bn:form.name_bn.trim()||form.name_en.trim(),name_en:form.name_en.trim(),category_type:type,active:true,sort_order:max+1});if(error)onToast({type:'error',text:`${t.failed} ${errorText(error)}`});else{setForm({name_bn:'',name_en:''});onToast({type:'success',text:t.categoryAdded});await load()}}async function toggle(c:Category){const {error}=await supabase.from('categories').update({active:!c.active}).eq('id',c.id);if(error)onToast({type:'error',text:`${t.failed} ${errorText(error)}`});else{onToast({type:'success',text:t.updated});await load()}}return <><PageHeader title={t.settings} subtitle={t.categories}/><section className="card"><div className="tabs"><button className={type==='income'?'active':''} onClick={()=>setType('income')}>{t.incomeCategory}</button><button className={type==='expense'?'active':''} onClick={()=>setType('expense')}>{t.expenseCategory}</button></div><form className="mini-form" onSubmit={add}><Field label={t.bengaliName}><input value={form.name_bn} onChange={e=>setForm({...form,name_bn:e.target.value})}/></Field><Field label={t.englishName}><input value={form.name_en} onChange={e=>setForm({...form,name_en:e.target.value})} required/></Field><button className="btn primary">＋ {t.addCategory}</button></form><div className="table-list">{cats.filter(c=>c.category_type===type).map(c=><div className="ledger-row" key={c.id}><div><b>{language==='bn'?c.name_bn:c.name_en}</b><small>{c.name_en}</small></div><div className="ledger-side"><ActivityBadge active={c.active} t={t}/><button className="text-btn" onClick={()=>void toggle(c)}>{c.active?t.deactivate:t.activate}</button></div></div>)}</div></section><UserManagement language={language} currentUserId={profile.id} onToast={onToast}/>
<section className="card security-note"><b>{t.profile}</b><p>{t.signedInAs}: {profile.full_name} · {roleLabel(profile.role,t)}</p><small>Authentication and permissions are handled by Supabase Auth + Row Level Security.</small></section></>}
function ReceiptTools({language,role,transactionType,transactionId,onToast}:{language:Language;role:AppRole;transactionType:'income'|'expense';transactionId:string;onToast:(v:Toast)=>void}){const t=copy[language];const [attachments,setAttachments]=useState<any[]>([]);const [busy,setBusy]=useState(false);const load=useCallback(async()=>{const column=transactionType==='income'?'income_transaction_id':'expense_transaction_id';const {data}=await supabase.from('attachments').select('id,storage_path,original_file_name,mime_type').eq(column,transactionId).order('created_at',{ascending:false});setAttachments(data??[])},[transactionType,transactionId]);useEffect(()=>{void load()},[load]);async function upload(file:File){if(!file)return;if(file.size>5*1024*1024){onToast({type:'error',text:'Receipt must be 5 MB or smaller.'});return}const allowed=['application/pdf','image/jpeg','image/png','image/webp'];if(!allowed.includes(file.type)){onToast({type:'error',text:'Use PDF, JPG, PNG or WebP.'});return}setBusy(true);const {data:userData}=await supabase.auth.getUser();const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=`${transactionType}/${transactionId}/${crypto.randomUUID()}-${safe}`;const {error:upError}=await supabase.storage.from('receipts').upload(path,file,{contentType:file.type,upsert:false});if(upError){setBusy(false);onToast({type:'error',text:`${t.uploadFailed} ${errorText(upError)}`});return}const payload:any=transactionType==='income'?{income_transaction_id:transactionId,storage_path:path,original_file_name:file.name,mime_type:file.type,file_size_bytes:file.size,uploaded_by:userData.user?.id??null}:{expense_transaction_id:transactionId,storage_path:path,original_file_name:file.name,mime_type:file.type,file_size_bytes:file.size,uploaded_by:userData.user?.id??null};const {error}=await supabase.from('attachments').insert(payload);setBusy(false);if(error){await supabase.storage.from('receipts').remove([path]);onToast({type:'error',text:`${t.uploadFailed} ${errorText(error)}`});return}onToast({type:'success',text:t.saved});await load()}async function openAttachment(a:any){const {data,error}=await supabase.storage.from('receipts').createSignedUrl(a.storage_path,300);if(error){onToast({type:'error',text:errorText(error)});return}window.open(data.signedUrl,'_blank','noopener,noreferrer')}return <div className="receipt-tools">{attachments.map(a=><button className="text-btn" key={a.id} onClick={()=>void openAttachment(a)}>↗ {t.receipt}</button>)}{(role==='admin'||role==='manager')&&<label className="receipt-upload">{busy?'…':'＋'}<input type="file" accept="application/pdf,image/jpeg,image/png,image/webp" onChange={e=>{const f=e.target.files?.[0];if(f)void upload(f);e.currentTarget.value=''}}/></label>}</div>}

function UserManagement({language,currentUserId,onToast}:{language:Language;currentUserId:string;onToast:(v:Toast)=>void}){const t=copy[language];const [users,setUsers]=useState<any[]>([]);const load=useCallback(async()=>{const {data,error}=await supabase.from('profiles').select('id,full_name,role,active,preferred_language').order('full_name');if(error)onToast({type:'error',text:errorText(error)});else setUsers(data??[])},[onToast]);useEffect(()=>{void load()},[load]);async function update(id:string,patch:any){const {error}=await supabase.from('profiles').update(patch).eq('id',id);if(error)onToast({type:'error',text:errorText(error)});else{onToast({type:'success',text:t.updated});await load()}}return <section className="card"><div className="section-title"><h2>{t.users}</h2><span className="count">{users.length}</span></div><div className="table-list">{users.map(u=><div className="ledger-row" key={u.id}><div><b>{u.full_name||u.id.slice(0,8)}</b><small>{u.preferred_language==='bn'?'বাংলা':'English'} · {u.active?t.active:t.inactive}</small></div><div className="user-controls"><select value={u.role} onChange={e=>void update(u.id,{role:e.target.value})}><option value="admin">{t.admin}</option><option value="manager">{t.manager}</option><option value="viewer">{t.viewer}</option></select><button className="text-btn" disabled={u.id===currentUserId&&u.active} onClick={()=>void update(u.id,{active:!u.active})}>{u.active?t.deactivate:t.activate}</button></div></div>)}</div><small className="muted">Create authentication accounts from Supabase Authentication. This screen controls their application role and active status.</small></section>}

function Field({label,children,wide}:{label:string;children:ReactNode;wide?:boolean}){return <label className={`field ${wide?'wide':''}`}><span>{label}</span>{children}</label>}

export default App
